insert into public.exams(slug,title,source,year) values ('pc-sp-2023-investigador','Polícia Civil SP 2023 — Investigador de Polícia — Versão 1','pc','2023') on conflict(slug) do update set title=excluded.title,source=excluded.source,year=excluded.year;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Noções de Informática','Em um computador com Microsoft Windows 10, em sua configuração padrão, um usuário vê o seguinte conteúdo dentro da pasta C:\TEMP a partir do Explorador de Arquivos, onde uma configuração foi feita na pasta 2023. Ao abrir a janela de linha de comando e digitar DIR na mesma pasta C:\TEMP, a pasta 2023, apesar de existir, não é exibida, como apresentado a seguir. Isso significa que a pasta 2023 está',null,'{"original": ["/pc-sp-2023-investigador/q1-1.png"]}','["protegida como somente leitura.", "criptografada.", "compactada.", "na lixeira do Windows.", "oculta."]'::jsonb,'E',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Noções de Informática','Tem-se o seguinte documento, criado no Microsoft Word 2016, em sua configuração padrão, com uma tabela de 1 linha e 1 coluna, com um texto formatado em negrito e itálico. Com o cursor após a palavra SP, ao pressionar TAB uma nova linha é criada. Para que o texto a ser digitado na segunda linha da tabela esteja formatado com sublinhado, apenas, é preciso clicar',null,'{"original": ["/pc-sp-2023-investigador/q2-1.png"]}','["uma vez no ícone Sublinhado, clicar uma vez no ícone Negrito e clicar uma vez no ícone Itálico.", "uma vez no ícone Sublinhado, apenas.", "uma vez no ícone Negrito e clicar no ícone Itálico, apenas.", "duas vezes no ícone Sublinhado, apenas.", "uma vez no ícone Limpar Formatação."]'::jsonb,'A',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Noções de Informática','Tem-se a seguinte planilha, criada no Microsoft Excel 2016, em sua configuração padrão, em dois momentos, ANTES e DEPOIS. ANTES DEPOIS A diferença entre os dois momentos, é que foi aplicado um AutoFiltro em DEPOIS. Assinale a alternativa que indica, respectivamente, qual(is) é(são) a(s) coluna(s) que está(ão) sendo filtrada(s) e a função que deve ser inserida na célula D1 para somar apenas os valores que estão sen- do exibidos, filtrados. Neste caso, deve exibir 336.',null,'{"original": ["/pc-sp-2023-investigador/q3-1.png"]}','["Código e Valor … =SOMA(D3:D7)", "Código, Nome e Valor … =SOMA(D3:D7)", "Nome … =SUBTOTAL(9;D3:D7)", "Código e Valor … =SOMASE(D3:D7;VERDADEIRO)", "Código, Nome e Valor … =SUBTOTAL(9;D3:D7)"]'::jsonb,'C',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Noções de Informática','Paulo redigiu uma mensagem de correio eletrônico usando o Microsoft Outlook 2016, em sua configura- ção padrão, para Rafaela, Antônio e Carlos. Rafaela, ao receber, clicou em Responder a todos e, sem alterar os destinatários na mensagem preparada automaticamente pelo Outlook, clicou em Enviar. Antônio e Carlos fizeram exatamente o mesmo. No final, Paulo recebeu 3 respos- tas. Rafaela recebeu 2 respostas apenas. Antônio rece- beu 2 respostas apenas. Carlos não recebeu nenhuma resposta. Considerando que todos enviaram e recebe- ram as mensagens com sucesso, isso significa que',null,'{"original": ["/pc-sp-2023-investigador/q4-1.png"]}','["Carlos estava no email original de Paulo no campo Cco.", "Antônio estava no email original de Paulo no campo Cco.", "Carlos estava no email original de Paulo no campo Cc.", "Rafaela estava no email original de Paulo no campo Cco.", "Carlos estava no email original de Paulo no campo Para."]'::jsonb,'A',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Noções de Informática','Tem-se uma imagem parcial de uma reunião criada e em andamento no Microsoft Teams, em sua configuração padrão, a partir do computador de João. A seguir, tem-se uma imagem, também parcial, dos parti- cipantes dessa reunião. Assinale a alternativa que indica quais participantes irão conseguir ouvir João.',null,'{"original": ["/pc-sp-2023-investigador/q5-1.png"]}','["Aaron Baxter e Daniela Madera, apenas.", "Aaron Baxter, apenas.", "Audi Kapoor, Aaron Baxter e Daniela Madera, apenas.", "Nenhum participante.", "Aaron Baxter, Daniela Madera e os outros 14 convi- dados, apenas."]'::jsonb,'D',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Noções de Informática','Ao digitar a mensagem a seguir na rede social Whatsapp, assinale a alternativa que indica como o texto ficará for- matado para o destinatário. *Atenção*: _não_ haverá prorrogação de data.',null,'{"original": ["/pc-sp-2023-investigador/q6-1.png"]}','["*Atenção*: _não_ haverá prorrogação de data.", "Atenção: não haverá prorrogação de data.", "Atenção: não haverá prorrogação de data.", "Atenção: não haverá prorrogação de data.", "Atenção: não haverá prorrogação de data."]'::jsonb,'E',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Noções de Informática','Sobre conceitos de URL, assinale a alternativa com o número da porta padrão para o protocolo HTTPS.',null,'{"original": ["/pc-sp-2023-investigador/q7-1.png"]}','["0.", "443.", "80.", "8080.", "21."]'::jsonb,'B',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Noções de Informática','A capacidade de espaço de dispositivos de armazena- mento de dados é medida em',null,'{"original": ["/pc-sp-2023-investigador/q8-1.png"]}','["Bytes.", "Hertz.", "Pixels.", "Watts.", "Volts."]'::jsonb,'A',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Noções de Informática','O(A) é uma tentativa de tornar os recur- sos de um sistema indisponíveis para os seus utilizado- res. Não se trata de uma invasão do sistema, mas sim da sua invalidação por sobrecarga. São feitos geralmente para forçar o sistema vítima a reinicializar ou consumir todos os recursos (como memória ou processamento, por exemplo) de forma que ele não possa mais fornecer seu serviço. Assinale a alternativa que preenche corretamente a lacu- na do enunciado.',null,'{"original": ["/pc-sp-2023-investigador/q9-1.png"]}','["spoofing", "phishing", "Ataque de negação de serviço (DoS)", "ransomware", "engenharia social"]'::jsonb,'C',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Noções de Informática','Assinale a alternativa que indica um software que pode ser usado para acessar a DeepWeb.',null,'{"original": ["/pc-sp-2023-investigador/q10-1.png", "/pc-sp-2023-investigador/q10-2.png"]}','["Edge.", "Safari.", "Google Chrome.", "Tor.", "Bing. Noções de Lógica"]'::jsonb,'D',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Raciocínio Lógico','Três investigadores, P1, P2 e P3, atuam em distritos policiais distintos, sendo eles D4, D5 e D6, e, utilizam viaturas distintas, V7, V8 e V9, não necessariamente nas ordens apresentadas. Sabe-se que o investigador P3 uti- liza a viatura V7, mas não no distrito D4; quem atua no distrito D5 não utiliza a viatura V8; o investigador P1 não atua em D6; o investigador P2 não atua em D5; e a via- tura V9 é utilizada no distrito D4. Sendo assim, é correto afirmar que o investigador',null,'{"original": ["/pc-sp-2023-investigador/q11-1.png"]}','["P1 atua no distrito D5.", "P2 utiliza a viatura V9.", "P1 atua no distrito D4.", "P2 não utiliza a viatura V8.", "P3 não atua no distrito D5."]'::jsonb,'C',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Raciocínio Lógico','Considere a seguinte sequência de figuras: Mantendo-se a regularidade da sequência, a figura F 101 será igual à figura',null,'{"original": ["/pc-sp-2023-investigador/q12-1.png"]}','["F 7.", "F 4.", "F 3.", "F 1.", "F 5."]'::jsonb,'E',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Raciocínio Lógico','Considere a seguinte afirmação: “Todos os envolvidos foram julgados ou aguardam julga- mento, e o caso está sendo encerrado.” Uma negação lógica para a afirmação apresentada é:',null,'{"original": ["/pc-sp-2023-investigador/q13-1.png"]}','["Nenhum dos envolvidos foi julgado ou aguarda julga- mento, e o caso não está sendo encerrado.", "Existe envolvido que não foi julgado e não aguarda julgamento, ou o caso não está sendo encerrado.", "Nenhum dos envolvidos foi julgado ou aguarda julga- mento, ou o caso não está sendo encerrado.", "Existe envolvido que não foi julgado e não aguarda julgamento, e o caso não está sendo encerrado.", "Todos os envolvidos não foram julgados e não aguar- dam julgamento, e o caso não está sendo encerrado."]'::jsonb,'B',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Raciocínio Lógico','Após a investigação de um crime, foram identificadas como verdadeiras as seguintes afirmações levantadas durante a investigação e, portanto, passaram a ser pre- missas do relatório final: I. Alfa não é uma cúmplice. II. Se Beta é uma cúmplice, então Gama não é a autora. III. Se Gama não é a autora ou Delta não é uma das mandantes, então Alfa é uma cúmplice. IV. Se Delta não é uma das mandantes, então Épsilon não é o coautor e Zeta é um dos mandantes. Uma das conclusões que decorrem das premissas ver- dadeiras apresentadas e forma, juntamente com essas premissas, um argumento válido para ser utilizado no relatório final é que',null,'{"original": ["/pc-sp-2023-investigador/q14-1.png"]}','["Épsilon é o coautor.", "Beta é uma cúmplice.", "Épsilon não é o coautor.", "Zeta é inocente.", "Beta não é uma cúmplice."]'::jsonb,'E',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Raciocínio Lógico','Sabendo-se que a afirmação “Fulano é culpado e Beltra no é inocente” é falsa, e que a afirmação “se Fulano é culpado, então Beltrano é inocente” é verdadeira, tem-se, necessariamente, que é',null,'{"original": ["/pc-sp-2023-investigador/q15-1.png"]}','["falsidade que Fulano é culpado.", "falsidade que Beltrano é inocente.", "verdade que Fulano é culpado.", "verdade que Beltrano é inocente.", "verdade que Fulano e Beltrano são inocentes."]'::jsonb,'A',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Raciocínio Lógico','Considere a seguinte sequência numérica, em que 30 é o seu quarto elemento: …, 30, 42, 56, 72, 90, 110, 132, … O trigésimo elemento dessa sequência é o número',null,'{"original": ["/pc-sp-2023-investigador/q16-1.png"]}','["992.", "1 122.", "1 056.", "930.", "870. Língua Portuguesa"]'::jsonb,'A',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Língua Portuguesa','Leia o poema, para responder às questões de números 17 a 20. Sei que fazer o inconexo aclara as loucuras. Sou formado em desencontros. A sensatez me absurda. Os delírios verbais me terapeutam. Posso dar alegria ao esgoto (palavra aceita tudo). (E sei de Baudelaire que passou muitos meses tenso porque não encontrava um título para os seus poe- mas. Um título que harmonizasse os seus conflitos. Até que apareceu Flores do mal. A beleza e a dor. Essa antítese o acalmou.) As antíteses congraçam. (Manoel de Barros, Livro sobre nada.) Um dos recursos de que se vale o eu lírico para produzir efeitos de sentido poéticos consiste em',null,'{"original": ["/pc-sp-2023-investigador/contexto-17-20-1.png", "/pc-sp-2023-investigador/q17-1.png"]}','["declinar de seu ofício de poeta, ao se identificar com a dificuldade de Baudelaire de criar antíteses.", "tratar a poesia como projeto de contestação da lin- guagem, por meio do emprego de termos em desuso na língua.", "expressar sua subjetividade por meio de referên- cias à dificuldade do ofício de ser poeta, de modo a dar-lhe ares de importância.", "apresentar recriações, tais como a conjugação de substantivos, as quais ele chama de delírios verbais.", "propor ao leitor uma releitura do conceito de poesia, empregando verbos e adjetivos fora de contexto."]'::jsonb,'D',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Língua Portuguesa','Leia o poema, para responder às questões de números 17 a 20. Sei que fazer o inconexo aclara as loucuras. Sou formado em desencontros. A sensatez me absurda. Os delírios verbais me terapeutam. Posso dar alegria ao esgoto (palavra aceita tudo). (E sei de Baudelaire que passou muitos meses tenso porque não encontrava um título para os seus poe- mas. Um título que harmonizasse os seus conflitos. Até que apareceu Flores do mal. A beleza e a dor. Essa antítese o acalmou.) As antíteses congraçam. (Manoel de Barros, Livro sobre nada.) Os dois últimos versos – Essa antítese o acalmou.) / As antíteses congraçam. – expressam a ideia, desenvolvida no poema, de que a criação poética consiste em',null,'{"original": ["/pc-sp-2023-investigador/contexto-17-20-1.png", "/pc-sp-2023-investigador/q18-1.png"]}','["traduzir a subjetividade em dados reconhecíveis da realidade do leitor.", "imitar poetas consagrados, para também alcançar reconhecimento.", "desafiar a coerência e produzir efeitos estéticos a partir de expressões inusitadas.", "conciliar as expectativas do leitor com o máximo de criatividade da linguagem.", "conceber novas formas de abordar os temas, priori- zando a clareza das ideias."]'::jsonb,'C',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Língua Portuguesa','Leia o poema, para responder às questões de números 17 a 20. Sei que fazer o inconexo aclara as loucuras. Sou formado em desencontros. A sensatez me absurda. Os delírios verbais me terapeutam. Posso dar alegria ao esgoto (palavra aceita tudo). (E sei de Baudelaire que passou muitos meses tenso porque não encontrava um título para os seus poe- mas. Um título que harmonizasse os seus conflitos. Até que apareceu Flores do mal. A beleza e a dor. Essa antítese o acalmou.) As antíteses congraçam. (Manoel de Barros, Livro sobre nada.) As palavras “sensatez” (3o verso) e “congraçam” (11o verso) têm, respectivamente, como sinônimo:',null,'{"original": ["/pc-sp-2023-investigador/contexto-17-20-1.png", "/pc-sp-2023-investigador/q19-1.png"]}','["reserva e destroem.", "comedimento e conciliam.", "submissão e desgraçam.", "prudência e monopolizam.", "resolução e animam."]'::jsonb,'B',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Língua Portuguesa','Leia o poema, para responder às questões de números 17 a 20. Sei que fazer o inconexo aclara as loucuras. Sou formado em desencontros. A sensatez me absurda. Os delírios verbais me terapeutam. Posso dar alegria ao esgoto (palavra aceita tudo). (E sei de Baudelaire que passou muitos meses tenso porque não encontrava um título para os seus poe- mas. Um título que harmonizasse os seus conflitos. Até que apareceu Flores do mal. A beleza e a dor. Essa antítese o acalmou.) As antíteses congraçam. (Manoel de Barros, Livro sobre nada.) O pronome “o” em – Essa antítese o acalmou – repre- senta o complemento do verbo, tal como ocorre com a expressão destacada na passagem:',null,'{"original": ["/pc-sp-2023-investigador/contexto-17-20-1.png", "/pc-sp-2023-investigador/q20-1.png"]}','["Os delírios verbais me terapeutam.", "Sou formado em desencontros.", "… passou muitos meses tenso…", "Até que apareceu Flores do mal.", "… não encontrava um título para os seus poemas."]'::jsonb,'E',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Língua Portuguesa','Leia o texto, para responder às questões de números 21 a 25. A igualação e a desigualdade A ditadura da sociedade de consumo exerce um totalitarismo simétrico ao de sua irmã gêmea, a ditadura da organização desigual do mundo. A maquinaria da igualação compulsiva atua contra a mais bela energia do gênero humano, que se reconhece em suas diferenças e através delas se vincula. O melhor que o mundo tem está nos muitos mundos que o mundo contém, as diferentes músicas da vida, suas dores e cores: as mil e uma maneiras de viver e de falar, crer e criar, comer, trabalhar, dançar, brincar, amar, sofrer e festejar que temos descoberto ao longo de milhares e milhares de anos. A igualação, que nos uniformiza e nos apalerma, não pode ser medida. Não há computador capaz de registrar os crimes cotidianos que a indústria da cultura de massas comete contra o arco-íris humano e o humano direito à identidade. Mas seus demolidores progressos saltam aos olhos. O tempo vai se esvaziando de história e o espaço já não reconhece a assombrosa diversidade de suas partes. Através dos meios massivos de comunicação, os donos do mundo nos comunicam a obrigação que temos todos de nos contemplar num único espelho, que reflete os valores da cultura de consumo. Quem não tem não é: quem não tem carro, não usa sapato de marca ou perfume importado está fingindo existir. (Eduardo Galeano, De pernas pro ar: a escola do mundo ao avesso) É correto afirmar que o autor assume a tese de que, na sociedade de consumo,',null,'{"original": ["/pc-sp-2023-investigador/contexto-21-25-1.png", "/pc-sp-2023-investigador/q21-1.png"]}','["há uma estandardização que descaracteriza as indi- vidualidades.", "vive-se uma realidade projetada para preservar valores pessoais.", "existe uma desconstrução do sentido de vida social solidária.", "propaga-se a igualdade como forma de manter o senso de coletividade.", "propõe-se uma nova perspectiva de vida, fundada na fruição do momento."]'::jsonb,'A',null from public.exams where slug='pc-sp-2023-investigador' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer;
